use Civi\Lughauth\Features\Access\TenantConfig\Domain\ValueObject\Holder\TenantConfigRecoverPassEmailAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TenantConfigRecoverPassEmailAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class TenantConfigRecoverPassEmailAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getRecoverPassEmail returns null on a freshly created holder.
     */
    public function testRecoverPassEmailNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigRecoverPassEmailAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isRecoverPassEmailAssigned());
        $this->assertNull($holder->getRecoverPassEmail());
    }
}
class ImplWithTenantConfigRecoverPassEmailAttributeHolderUnitTest
{
    use TenantConfigRecoverPassEmailAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedRecoverPassEmailRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultRecoverPassEmail();
    }
}
